#include <iostream>

int sequence(int n) {
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return -1;
    } else if (n == 2) {
        return -1;
    } else {
        return sequence(n - 1) + sequence(n - 2) + sequence(n - 3);
    }
}

int main() {
    int n;
    std::cout << "Enter the value of n: ";
    std::cin >> n;

    int seq_num = sequence(n);
    std::cout << "The " << n << "th number in the sequence is: " << seq_num << std::endl;

    return 0;
}
